#!/bin/sh
# DNS-over-TLS (RFC 7858) on TCP 853, the protocol behind Android's
# Private DNS setting. dnsdist terminates TLS with Caddy's certificate for
# DOT_HOST and hands every query to the same dnsmasq that DoH uses, so the
# blocks and rewrites are identical. dnsdist rather than a plain TLS tunnel:
# it multiplexes many long-lived phone connections onto a few pooled ones to
# dnsmasq, which forks per TCP connection and caps them at 20.
set -eu
HERE="$(cd "$(dirname "$0")" && pwd)"
. "$HERE/env.sh"

NEW=/etc/dnsdist/dnsdist.conf.new
cat > "$NEW" <<CONF
-- Generated by deploy/server/dot.sh
addTLSLocal('0.0.0.0:853', '$ETC/dot/cert.pem', '$ETC/dot/key.pem',
  {provider='openssl', minTLSVersion='tls1.2'})
newServer({address='127.0.0.1:53', name='dnsmasq', healthCheckMode='up'})
-- Any client may ask: TLS over TCP cannot be spoofed into an amplifier.
setACL({'0.0.0.0/0', '::/0'})
setSecurityPollSuffix('')
-- Phones keep the connection open between queries.
setTCPRecvTimeout(10)
-- dnsmasq forks one child per TCP connection and stops accepting at 20:
-- keep the pool of connections to it small and recycle idle ones.
setMaxTCPClientThreads(4)
setMaxCachedTCPConnectionsPerDownstream(2)
setTCPDownstreamMaxIdleTime(60)
CONF
chgrp _dnsdist "$NEW"
chmod 640 "$NEW"
if ! dnsdist --check-config -C "$NEW" >/dev/null 2>&1; then
  echo "anssis-dot: generated dnsdist config invalid, keeping the live one" >&2
  rm -f "$NEW"
  exit 1
fi
CHANGED=0
cmp -s "$NEW" /etc/dnsdist/dnsdist.conf || CHANGED=1
mv "$NEW" /etc/dnsdist/dnsdist.conf

if command -v ufw >/dev/null && ufw status | grep -q active; then
  ufw allow 853/tcp comment anssiscanvdns-dot >/dev/null
fi
systemctl enable dnsdist anssis-dot-cert.path anssis-dot-cert.timer >/dev/null 2>&1
systemctl start anssis-dot-cert.path anssis-dot-cert.timer
# Copies the certificate and (re)starts dnsdist when it changed.
sh "$HERE/dot-cert.sh"
if [ "$CHANGED" = 1 ] && [ -f "$ETC/dot/cert.pem" ]; then systemctl restart dnsdist; fi
